{
  "name": "catalog_sync",
  "description": "Refresh the cached catalog of an environment from the live systems: Postgres schemas, functions, views, triggers (all databases), ES mappings, Kafka topics + schemas + last messages, Consul services; then the usage index. \"passports\" rebuilds the cached service passports, \"index\" only rebuilds catalog + usage from the cache. Takes seconds to minutes; if it answers \"running\", call it again with that job id. Run it when find says the catalog is empty or something is missing.",
  "group": "catalog",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "env": {
        "type": "string",
        "enum": [
          "dev"
        ],
        "default": "dev",
        "description": "Environment"
      },
      "what": {
        "type": "string",
        "enum": [
          "pg",
          "es",
          "kafka",
          "consul",
          "passports",
          "bitbucket",
          "confluence",
          "index",
          "all"
        ],
        "default": "all"
      },
      "only": {
        "type": "string",
        "description": "Comma list to limit: db names for pg, name parts for es/kafka, services for passports, spaces for confluence"
      },
      "spaces": {
        "type": "string",
        "description": "Confluence space keys, comma-separated (what=confluence)"
      },
      "full": {
        "type": "boolean",
        "default": false,
        "description": "Reconcile all Confluence page IDs and refresh every cached version"
      },
      "job": {
        "type": "string",
        "description": "A job id from an earlier \"running\" answer: wait for that job instead of starting a sync"
      }
    },
    "required": []
  }
}
